    internal static int RtFillRamp(emon.Port.Bitmap b, int ch) {
        // channel 0 of pixel (x, y) := (37 * (y * w + x)) mod 256; the other
        // channels := 255 - that, so a form reading the wrong one is caught.
        int w = emon.Port.BitmapW(b);
        int h = emon.Port.BitmapH(b);
        int x = 0;
        int y = 0;
        int v = 0;
        while (y < h) {
            x = 0;
            while (x < w) {
                v = (37 * ((y * w) + x)) % 256;
                emon.Port.BitmapSetU8(b, x, y, 0, v);
                if (ch > 1) {
                    emon.Port.BitmapSetU8(b, x, y, 1, 255 - v);
                }
                x += 1;
            }
            y += 1;
        }
        return 0;
    }
    internal static int RtSameCells(emon.Port.Cells a, emon.Port.Cells b) {
        // 1 when the two hold the same cells.
        int i = 0;
        int same = 1;
        if (emon.Port.CellsLen(a) != emon.Port.CellsLen(b)) {
            same = 0;
        }
        while (i < emon.Port.CellsLen(a)) {
            if (emon.Port.CellsAt(a, i) != emon.Port.CellsAt(b, i)) {
                same = 0;
            }
            i += 1;
        }
        return same;
    }
