    internal static int RtRamp19(emon.Port.Bitmap b) {
        int y = 0;
        int x = 0;
        while (y < 3) {
            x = 0;
            while (x < 3) {
                emon.Port.BitmapSetU8(b, x, y, 0, ((y * 3) + x) + 1);
                x += 1;
            }
            y += 1;
        }
        return 0;
    }
